UPDATE companies SET description='AKG North American Operations, operating as AKG of America, is headquartered in Mitchell, South Dakota. The business is part of the AKG Group, a global thermal management company that cites 100 years of industry experience. Ownership structure and founding year are not publicly disclosed on the company''s web pages.

The company develops and manufactures high-performance heat exchangers and cooling systems. Its product portfolio includes radiators, oil coolers, charge air coolers, pre-engineered coolers, cooling systems, compact coolers, electronics cooling modules, and the AKG Power Systems line. With approximately 3,000 employees worldwide, AKG operates global manufacturing facilities supported by regional engineering centers, offering both standard catalog products and customized thermal management solutions designed for easy installation, low maintenance, and energy efficiency.

AKG serves original equipment manufacturers across seven core sectors: power generation, renewable energy, off-highway and construction equipment, oil and gas, on-highway vehicles, railway, and compressor markets. The company emphasizes global engineering capabilities with local production to meet specific application requirements in each industry.

AKG differentiates itself through precision engineering, an ISO 9001-certified quality management system, and the AKG Green Thermal Solutions initiative aimed at helping customers achieve net-zero emission targets. Its quality policy centers on continuous improvement, customer knowledge, and on-time delivery of the right product.', certifications=ARRAY['ISO 9001','ISO 14001:2015']::text[], profile='{"capabilities": ["Heat exchanger manufacturing", "Thermal management system design", "Custom cooling solutions", "Standard cooling products", "Electronics cooling", "Power systems cooling", "Radiator production", "Oil cooler production", "Charge air cooler production", "Pre-engineered cooler assembly", "Compact cooler manufacturing", "Cooling system integration"], "industries": ["Power Generation", "Renewable Energy", "Off-Highway and Construction Equipment", "Oil & Gas", "On-Highway", "Railway", "Compressor"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Global engineering and manufacturing capabilities with local production", "Standard and customized thermal management solutions", "ISO 9001-certified quality management system", "AKG Green Thermal Solutions for sustainability and net-zero targets", "100 years of industry experience in thermal management"], "facts_used": ["Headquarters in Mitchell, South Dakota -> db", "3000 employees -> db", "ISO 9001 and ISO 14001:2015 certifications -> db, /quality", "Manufactures heat exchangers and cooling systems -> /quality", "Product lines: radiators, oil coolers, charge air coolers, pre-engineered coolers, cooling systems, compact coolers, electronics cooling, AKG Power Systems -> /", "Markets served: power generation, renewable energy, off-highway/construction, oil & gas, on-highway, railway, compressor -> /", "Global presence with local production and regional engineering support -> /", "AKG Green Thermal Solutions for sustainability -> /", "Quality policy: continuous improvement, customer knowledge, on-time delivery -> /quality", "100 years of industry experience claimed -> /", "LinkedIn URL -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We continuously develop and manufacture high-performance heat exchangers", "founded_year": "", "employee_count": "3000", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/akgofamerica/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='akg-north-american-operations' AND approved AND profile IS NULL;
