UPDATE companies SET description='Allied Wholesale Electrical Supply, Inc. (AWESI) is a family-owned electrical wholesale distributor headquartered in Anderson, Indiana. The company was founded in 1985 by Bob McCurdy with a simple premise: keep the products customers need in stock and treat every buyer like family. McCurdy and his son, Rob McCurdy, ran the business side by side for 16 years, adhering to those principles through several warehouse expansions.

Today AWESI operates a 54,000-square-foot central warehouse on the west side of Indianapolis, supplemented by branch locations in Indianapolis, Anderson, Bloomington, and Lafayette. The distributor stocks a broad range of electrical supplies including overhead service drop cable, service entrance cable, load centers, meter sockets, wiring devices, pole-line hardware, and fastening products. In 2016 the company acquired a plumbing distributor in Bloomington, adding plumbing supplies to its product mix.

Its product lines feature brands such as IDEAL Industries and Arlington Industries, covering categories from general-purpose wiring devices to harsh-environment and low-voltage components. The company reports that its customer base has grown exponentially while the staff—many with more than a decade of tenure—retains deep product knowledge.

The founding vision remains the company’s stated differentiator: maintaining immediate product availability and a family-oriented service culture. Leadership emphasizes that the knowledgeable, long-tenured team and the family atmosphere have persisted despite rapid growth, positioning AWESI among the largest independent distributors in Indiana and within the top 200 nationally.', certifications=ARRAY['UL Listed']::text[], profile='{"capabilities": ["Overhead Service Drop", "Service Entrance Cable", "Service Drop Cable", "Load Centers & Service Entrance Equipment", "Service Masts, House Brackets, Insulators", "Meter Sockets & Mounting Assemblies", "Wiring Devices & Data", "General Purpose Wiring Devices", "Consumer Packaged Wiring Devices", "Harsh Environment Wiring Devices", "Low Voltage Wiring Devices", "Miniature & Appliance Wiring Devices", "Fastening Hardware", "Builders Products", "Pole Line & Distribution Hardware"], "industries": ["Electrical wholesale distribution", "Plumbing wholesale distribution"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Maintains extensive in-stock inventory to meet immediate customer needs", "Family-oriented service culture with staff averaging over a decade of tenure", "Operates a 54,000 sq. ft. central warehouse plus four Indiana branch locations", "Ranked among the largest independent electrical distributors in Indiana and top 200 nationally", "Expanded into plumbing distribution through 2016 acquisition of a Bloomington distributor"], "facts_used": ["Founded in 1985 by Bob McCurdy -> /about-us", "Family-owned since 1985 -> /about-us", "Rob McCurdy purchased business in 2009 -> /about-us", "54,000 sq ft warehouse in Indianapolis -> /about-us", "Branches in Indianapolis, Anderson, Bloomington, Lafayette -> /about-us", "Acquired plumbing distributor in Bloomington in 2016 -> /about-us", "One of largest independent distributors in Indiana, top 200 nationally -> /about-us", "Staff with over a decade tenure, family atmosphere -> /about-us", "UL Listed certification -> db", "Product categories: overhead service drop, service entrance cable, load centers, meter sockets, wiring devices, pole line hardware -> db", "Brands carried: IDEAL Industries, Arlington Industries -> db", "Headquarters: Anderson, Indiana -> db"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "AWESI has grown to one of the largest Independent Distributors in Indiana", "founded_year": "1985", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='allied-wholesale-electrical-supply-inc' AND approved AND profile IS NULL;
