UPDATE companies SET description='ASH Industries was founded in 1991 in Lafayette, Louisiana, by Hartie and Kim Spence. The company remains headquartered in Lafayette, where all production takes place in a facility that has expanded to include more than 25 molding machines, a full tool shop, and a Class 7 cleanroom.

The company specializes in plastic, metal, and silicone injection molding, offering in-house tooling design, build, and maintenance alongside secondary operations such as CNC machining, ultrasonic welding, hot stamping, pad printing, assembly, and packaging. Capabilities also include 3D printing, rotational molding, and liquid silicone rubber molding. Materials range from commodity resins like ABS and polypropylene to high-performance polymers such as PEEK and Ultem, as well as stainless steels (17-4, 316, S7) and low-alloy steels (8620, 4140). Production volumes span from 1,000-piece runs to millions of assemblies.

ASH serves medical and surgical device manufacturers, producing components that require ISO 13485 certification and cleanroom conditions. The company also supplies structural parts for laser light show systems. Its engineering-driven approach emphasizes early design-for-manufacturing involvement, just-in-time delivery, and theory-of-constraints methodologies to reduce inventory and optimize production schedules.

The SuperMold program differentiates ASH by delivering steel tooling and first articles in as little as 10 days for $4,900, replacing traditional short-life prototype tooling. Combined with ISO 9001:2015 and ISO 13485:2016 certification, ITAR registration, and a fully integrated in-house workflow, the company positions itself for complex, tight-tolerance projects that demand speed and regulatory compliance.', certifications=ARRAY['ISO 9001:2015','ISO 13485:2016','Class 7 Cleanroom','ITAR Registered']::text[], profile='{"capabilities": ["Plastic Injection Molding", "Metal Injection Molding (MIM)", "Silicone Injection Molding (LIM)", "Liquid Silicone Rubber Injection Molding", "Rotational Molding", "In-House Tooling (Mold Design, Build, Maintenance)", "3D Printing", "CNC Machining", "Ultrasonic Welding", "Hot Stamping", "Pad Printing", "Assembly", "Packaging", "Design for Manufacturing (DFM)", "Prototyping", "Overmolding", "Thermoset Molding"], "industries": ["Medical Devices", "Surgical Devices", "Laser Light Show Systems"], "materials": ["ABS", "Polypropylene (PP)", "Polyethylene (PE)", "Glass-Filled Nylon (GF Nylon)", "PEEK", "Ultem", "Stainless Steel 17-4", "Stainless Steel 316", "Stainless Steel S7", "Low Alloy Steel 8620", "Low Alloy Steel 4140", "Silicone", "Thermoset resins"], "equipment": [], "volume": "1,000 to millions of parts", "lead_time": "10 days for tooling and first articles (SuperMold program)", "tolerances": "", "built_on": ["SuperMold program: steel tooling and first articles in as little as 10 days for $4,900", "In-house tooling design, build, and maintenance", "Engineering-driven DFM involvement from concept", "ISO 9001:2015 and ISO 13485:2016 certified with Class 7 cleanroom", "ITAR registered, all manufacturing in Lafayette, LA"], "facts_used": ["Founded 1991 by Hartie and Kim Spence -> /about-us", "Family-owned, second generation leadership -> /about-us", "Headquarters Lafayette, Louisiana -> /, /about-us", "Over 100 employees, 25+ molding machines, full tool shop -> /about-us", "ISO 9001:2015, ISO 13485:2016, Class 7 Cleanroom, ITAR Registered -> /, /about-us", "Plastic, metal, silicone injection molding; in-house tooling; secondary operations -> /", "Materials: ABS, PP, PE, GF Nylon, PEEK, Ultem; stainless steels 17-4, 316, S7; low alloy steels 8620, 4140 -> /", "SuperMold program: tooling and first articles in 10 days for $4,900 -> /", "Serves medical/surgical devices and laser light show components -> /about-us", "JIT and Theory of Constraints methodologies -> /about-us", "Volume: thousands to millions of parts -> /about-us", "Min order: 1,000 parts or less -> /", "All manufacturing in-house, US-owned -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "All manufacturing is done in-house at our Lafayette, Louisiana, facility.", "founded_year": "1991", "employee_count": "100+", "cage_code": "", "min_order": "1,000 parts or less", "export_compliance": ["ITAR Registered"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ash-industries' AND approved AND profile IS NULL;
